import Image from "next/image";

import FOOTER from "@/components/FOOTER";
import MENU from "@/components/MENU";
import circus from "@public/images/profiles/circus.webp";
import jm from "@public/images/profiles/jm.webp";
import dark from "@public/images/profiles/jmdark-min.webp";
import lite from "@public/images/profiles/jmlite-min.webp";
import waves from "@public/images/profiles/waves.webp";
import { Metadata } from "next";
import Script from "next/script";
import { safeJsonLd } from "@/lib/jsonld";

export const metadata: Metadata = {
  title: "PFPs",
  description: "All the profile photos I've used over the years.",
  alternates: {
    canonical: "https://jaspermayone.com/pfp",
  },
};

const profilePhotos = [
  { src: "/images/profiles/jm.webp", name: "Current Profile Photo" },
  { src: "/images/profiles/jmdark-min.webp", name: "Dark Theme Profile" },
  { src: "/images/profiles/jmlite-min.webp", name: "Light Theme Profile" },
  { src: "/images/profiles/circus.webp", name: "Circus Profile" },
  { src: "/images/profiles/waves.webp", name: "Waves Profile" },
];

const pfpPageSchema = {
  "@context": "https://schema.org",
  "@graph": [
    {
      "@type": "WebPage",
      "@id": "https://jaspermayone.com/pfp#webpage",
      url: "https://jaspermayone.com/pfp",
      name: "Profile Photos - Jasper Mayone",
      description: "All the profile photos I've used over the years.",
      isPartOf: {
        "@id": "https://jaspermayone.com/#website",
      },
      about: {
        "@id": "https://jaspermayone.com/#person",
      },
      mainEntity: {
        "@id": "https://jaspermayone.com/pfp#gallery",
      },
      breadcrumb: {
        "@type": "BreadcrumbList",
        "@id": "https://jaspermayone.com/pfp#breadcrumb",
        itemListElement: [
          {
            "@type": "ListItem",
            position: 1,
            name: "Home",
            item: "https://jaspermayone.com",
          },
          {
            "@type": "ListItem",
            position: 2,
            name: "Profile Photos",
            item: "https://jaspermayone.com/pfp",
          },
        ],
      },
    },
    {
      "@type": "ImageGallery",
      "@id": "https://jaspermayone.com/pfp#gallery",
      name: "Jasper Mayone Profile Photos",
      description:
        "A collection of profile photos used by Jasper Mayone over the years",
      author: {
        "@id": "https://jaspermayone.com/#person",
      },
      image: profilePhotos.map((photo, index) => ({
        "@type": "ImageObject",
        name: photo.name,
        contentUrl: `https://jaspermayone.com${photo.src}`,
        position: index + 1,
      })),
    },
  ],
};

const paths = [jm, dark, lite, circus, waves];

export default function PFP() {
  return (
    <>
      <Script
        id="pfp-schema"
        type="application/ld+json"
        dangerouslySetInnerHTML={{
          __html: safeJsonLd(pfpPageSchema),
        }}
      />
      <div className="flex min-h-screen flex-col">
        <MENU pageFirstWord="PFPs" />
        <main className="flex-1">
          <div className="mx-5 mt-4 mb-4">
            <h1
              className="mb-4 text-xl font-semibold text-zinc-800 underline dark:text-white"
              style={{ fontFamily: "var(--font-balgin)" }}
            >
              Profile Photos
            </h1>

            <p className="mb-5 text-zinc-600 dark:text-white/70">
              Here&apos;s all the profile photos I&apos;ve used over the years
            </p>

            <div className="grid grid-cols-4 gap-4 md:grid-cols-5 lg:grid-cols-6">
              {paths.map((path) => (
                <div
                  key={path.src}
                  className="aspect-square size-50 overflow-hidden rounded-[10%] bg-white/50 p-1 dark:bg-zinc-800/20"
                >
                  <Image
                    src={path}
                    alt="one of jasper's previous profile photos"
                    width={200}
                    height={200}
                    aria-label="one of jasper's previous profile photos"
                    placeholder="blur"
                    priority={true}
                    className="h-full w-full rounded-[8%] object-cover object-center"
                  />
                </div>
              ))}
            </div>
          </div>
        </main>
        <FOOTER />
      </div>
    </>
  );
}

"use client";
import ConfettiWrapper from "@/components/ConfettiWrapper";
import ExternalLink from "@/components/ExternalLink";
import FOOTER from "@/components/FOOTER";
import MENU from "@/components/MENU";
import RoundedImage from "@/components/RoundedImage";
import { getAge } from "@/lib/defs";
import JmDark from "@public/images/jmdark-min.webp";
import JmLight from "@public/images/jmlite-min.webp";
import { useSyncExternalStore } from "react";

// Subscribe function for useSyncExternalStore
function subscribeToLightMode(callback: () => void) {
  const mediaQuery = window.matchMedia("(prefers-color-scheme: light)");
  mediaQuery.addEventListener("change", callback);
  return () => mediaQuery.removeEventListener("change", callback);
}

// Get current snapshot for client
function getLightModeSnapshot() {
  return window.matchMedia("(prefers-color-scheme: light)").matches;
}

// Get snapshot for server-side rendering
function getLightModeServerSnapshot() {
  return false;
}

export default function Home() {
  const isLightMode = useSyncExternalStore(
    subscribeToLightMode,
    getLightModeSnapshot,
    getLightModeServerSnapshot
  );

  const imgpath = isLightMode ? JmDark : JmLight;

  return (
    <div className="mx-auto flex min-h-screen min-w-screen flex-col">
      <MENU pageFirstWord="Jasper" pageSecondWord="Mayone" />
      <main className="flex-1">
        <ConfettiWrapper />
        <div className="mx-5 mt-5 mb-5 flex flex-col gap-8 md:flex-row">
          <div className="mx-auto mt-8 w-64 shrink-0 overflow-hidden md:mx-0 md:self-start">
            <RoundedImage
              src={imgpath}
              alt="Jasper Mayone"
              size={250}
              isPriority={true} // Add priority for above-the-fold images
              transitionName="profile-image"
            />
          </div>
          <div className="flex flex-col justify-center">
            <div className="space-y-4">
              <p className="text-xl font-medium">
                <span style={{ fontFamily: "var(--font-balgin)" }}>
                  Jasper Mayone [<i>he/they</i>]
                </span>{" "}
                <span className="font-normal text-zinc-700 dark:text-white/70">
                  is a {getAge()}-year-old college student from rural Vermont,
                  currently residing in Boston.
                </span>
              </p>
              <p className="text-sm text-zinc-600 dark:text-white/70">
                A computer science major at{" "}
                <ExternalLink className="lnk" href="https://wit.edu">
                  Wentworth Institute of Technology
                </ExternalLink>{" "}
                in Boston, Massachusetts. When not in school or at work,
                Jasper&apos;s hobbies include reading, being in the great
                outdoors, photography, computer programming, cooking, and
                running away to join the circus.
              </p>
              <p className="text-sm text-zinc-600 dark:text-white/70">
                An avid organizer and big picture thinker, you can often find
                them scheming up some sort of business venture. From developing
                a small app to drafting large scale plans for a world domination
                scheme, Jasper is always looking for ways to combine their
                diverse interests and skills into enterprising projects. This
                knack for organization and leadership has opened doors for
                Jasper to take on exciting roles in various projects and
                adventures, both close to home and abroad.
              </p>
              <p className="text-sm text-zinc-600 dark:text-white/70">
                Recently they&apos;ve been focusing their time (outside of their
                degree) on{" "}
                <ExternalLink
                  className="lnk"
                  href="https://patchworklabs.org"
                  aria-label="patchworklabs.org"
                >
                  Patchwork Labs
